  ('text-gita-03-001-deva', 'release-lb-gita-open-c6fce3959544', 'verse-gita-03-001', 'sa', 'Deva', 'canonical-script', 'अर्जुन उवाच
ज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन।
तत्किं कर्मणि घोरे मां नियोजयसि केशव॥', JSON_ARRAY(1, 2), NULL, NULL, 'Bhagavad Gita 3.1', 'published'),
  ('text-gita-03-001-latn', 'release-lb-gita-open-c6fce3959544', 'verse-gita-03-001', 'sa', 'Latn', 'transliteration', 'arjuna uvācha
